s/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4123,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 16.1-3\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T5cf,śrī-bhagavān uvāca – the Supreme Personality of Godhead said; abhayam – fearlessness; sattva-saṁśuddhiḥ – purification of one’s existence; jñāna – in knowledge; yoga – of linking up; vyavasthitiḥ – the situation; dānam – charity; damaḥ – controlling the mind; ca – and; yajñaḥ – performance of sacrifice; ca – and; svādhyāyaḥ – study of Vedic literature; tapaḥ – austerity; ārjavam – simplicity; ahiṁsā – nonviolence; satyam – truthfulness; akrodhaḥ – freedom from anger; tyāgaḥ – renunciation; śāntiḥ – tranquillity; apaiśunam – aversion to fault-finding; dayā – mercy; bhūteṣu – towards all living entities; aloluptvam – freedom from greed; mārdavam – gentleness; hrīḥ – modesty; acāpalam – determination; tejaḥ – vigor; kṣamā – forgiveness; dhṛtiḥ – fortitude; śaucam – cleanliness; adrohaḥ – freedom from envy; na – not; ati-mānitā – expectation of honor; bhavanti – are; sampadam – the qualities; daivīm – the transcendental nature; abhijātasya – of one who is born of; bhārata – O son of Bharata.26:T475,In the beginning of the Fifteenth Chapter, the banyan tree of this material world was explained. The extra roots coming out of it were compared to the activities of the living entities, some auspicious, some inauspicious. In the Ninth Chapter, also, the devas, or godly, and the asuras, the ungodly, or demons, were explained. Now, according to Vedic rites, activities in the mode of goodness are considered auspicious for progress on the path of liberation, and such activities are known as daivī prakṛti, transcendental by nature. Those who are situated in the transcendental nature make progress on the path of liberation. For those who are acting in the modes of passion and ignorance, on the other hand, there is no possibility of liberation. Either they will have to remain in this material world as human beings, or they will descend among the species of animals or even lower life forms. In this Sixteenth Chapter the Lord explains both the transcendental nature and its attendant qualities and the demoniac nature and its qualities. He also explains the advantages and disadvantages of these qualities.27:T603,"])self.__next_f.push([1,"In the varṇāśrama institution the sannyāsī, or the person in the renounced order of life, is considered to be the head or the spiritual master of all the social statuses and orders. A brāhmaṇa is considered to be the spiritual master of the three other sections of a society, namely, the kṣatriyas, the vaiśyas and the śūdras, but a sannyāsī, who is on the top of the institution, is considered to be the spiritual master of the brāhmaṇas also. For a sannyāsī, the first qualification should be fearlessness. Because a sannyāsī has to be alone without any support or guarantee of support, he has simply to depend on the mercy of the Supreme Personality of Godhead. If one thinks, “After I leave my connections, who will protect me?” he should not accept the renounced order of life. One must be fully convinced that Kṛṣṇa or the Supreme Personality of Godhead in His localized aspect as Paramātmā is always within, that He is seeing everything, and He always knows what one intends to do. One must thus have firm conviction that Kṛṣṇa as Paramātmā will take care of a soul surrendered to Him. “I shall never be alone,” one should think. “Even if I live in the darkest regions of a forest I shall be accompanied by Kṛṣṇa, and He will give me all protection.” That conviction is called abhayam, fearlessness. This state of mind is necessary for a person in the renounced order of life."])self.__next_f.push([1,"28:T83f,"])self.__next_f.push([1,"Then he has to purify his existence. There are so many rules and regulations to be followed in the renounced order of life. Most important of all, a sannyāsī is strictly forbidden to have any intimate relationship with a woman. He is even forbidden to talk with a woman in a secluded place. Lord Caitanya was an ideal sannyāsī, and when He was at Purī His feminine devotees could not even come near to offer their respects. They were advised to bow down from a distant place. This is not a sign of hatred for women as a class, but it is a stricture imposed on the sannyāsī not to have close connections with women. One has to follow the rules and regulations of a particular status of life in order to purify his existence. For a sannyāsī, intimate relations with women and possession of wealth for sense gratification are strictly forbidden. The ideal sannyāsī was Lord Caitanya Himself, and we can learn from His life that He was very strict in regards to women. Although He is considered to be the most liberal incarnation of Godhead, accepting the most fallen conditioned souls, He strictly followed the rules and regulations of the sannyāsa order of life in connection with association with women. One of His personal associates, namely Choṭa Haridāsa, was associated with Lord Caitanya along with His other confidential personal associates, but somehow or other this Choṭa Haridāsa looked lustily on a young woman, and Lord Caitanya was so strict that He at once rejected him from the society of His personal associates. Lord Caitanya said, “For a sannyāsī or anyone who is aspiring to get out of the clutches of material nature and trying to elevate himself to the spiritual nature and go back home, back to Godhead, for him, looking toward material possessions and women for sense gratification – not even enjoying them, but just looking toward them with such a propensity – is so condemned that he had better commit suicide before experiencing such illicit desires.” So these are the processes for purification."])self.__next_f.push([1,"29:T4f4, The next item is jñāna-yoga-vyavasthiti: being engaged in the cultivation of knowledge. Sannyāsī life is meant for distributing knowledge to the householders and others who have forgotten their real life of spiritual advancement. A sannyāsī is supposed to beg from door to door for his livelihood, but this does not mean that he is a beggar. Humility is also one of the qualifications of a transcendentally situated person, and out of sheer humility the sannyāsī goes from door to door, not exactly for the purpose of begging, but to see the householders and awaken them to Kṛṣṇa consciousness. This is the duty of a sannyāsī. If he is actually advanced and so ordered by his spiritual master, he should preach Kṛṣṇa consciousness with logic and understanding, and if one is not so advanced he should not accept the renounced order of life. But even if one has accepted the renounced order of life without sufficient knowledge, he should engage himself fully in hearing from a bona fide spiritual master to cultivate knowledge. A sannyāsī, or one in the renounced order of life, must be situated in fearlessness, sattva-saṁśuddhi (purity) and jñāna-yoga (knowledge).2a:T5ad,"])self.__next_f.push([1,"Tapas, or austerity, is especially meant for the retired life. One should not remain a householder throughout his whole life; he must always remember that there are four divisions of life – brahmacarya, gṛhastha, vānaprastha and sannyāsa. So after gṛhastha, householder life, one should retire. If one lives for a hundred years, he should spend twenty-five years in student life, twenty-five in householder life, twenty-five in retired life and twenty-five in the renounced order of life. These are the regulations of the Vedic religious discipline. A man retired from household life must practice austerities of the body, mind and tongue. That is tapasya. The entire varṇāśrama-dharma society is meant for tapasya. Without tapasya, or austerity, no human being can get liberation. The theory that there is no need of austerity in life, that one can go on speculating and everything will be nice, is recommended neither in the Vedic literature nor in Bhagavad-gītā. Such theories are manufactured by show-bottle spiritualists who are trying to gather more followers. If there are restrictions, rules and regulations, people will not become attracted. Therefore those who want followers in the name of religion, just to have a show only, don’t restrict the lives of their students, nor their own lives. But that method is not approved by the Vedas."])self.__next_f.push([1,"2b:T511,Ahiṁsā means not arresting the progressive life of any living entity. One should not think that since the spirit spark is never killed even after the killing of the body there is no harm in killing animals for sense gratification. People are now addicted to eating animals, in spite of having an ample supply of grains, fruits and milk. There is no necessity for animal killing. This injunction is for everyone. When there is no alternative, one may kill an animal, but it should be offered in sacrifice. At any rate, when there is an ample food supply for humanity, persons who are desiring to make advancement in spiritual realization should not commit violence to animals. Real ahiṁsā means not checking anyone’s progressive life. The animals are also making progress in their evolutionary life by transmigrating from one category of animal life to another. If a particular animal is killed, then his progress is checked. If an animal is staying in a particular body for so many days or so many years and is untimely killed, then he has to come back again in that form of life to complete the remaining days in order to be promoted to another species of life. So their progress should not be checked simply to satisfy one’s palate. This is called ahiṁsā."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4123,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"1-3\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 1-3\",\"advanced_view_url_path\":\"/en/library/bg/16/advanced-view/#bb3626\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/16/1-3/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/16/1-3/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/16/1-3/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/16/1-3/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/16/1-3/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/16/1-3/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/16/1-3/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/16/1-3/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/16/1-3/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu/library/bg/16/1-3/\"},{\"display_name\":\"日本語 (Japanese)\",\"language_code\":\"ja\",\"enabled\":true,\"url_path\":\"/ja/library/bg/16/1-3/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/16/1-3/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/16/1-3/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/16/1-3/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/16/1-3/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/16/1-3/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/16/1-3/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/16/1-3/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/16/1-3/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/16/1-3/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/16/\",\"title\":\"Chapter Sixteen: The Divine and Demoniac Natures\"}],\"url_path\":\"/en/library/bg/16/1-3/\",\"bb\":3626,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/16/\",\"title\":\"Chapter Sixteen\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/16/4/\",\"title\":\"TEXT 4\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":4124,\"bb\":568422,\"url_path\":\"/en/library/bg/16/1-3/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
अभयं सत्त्वसंश‍ुद्धिर्ज्ञानयोगव्यवस्थिति: ।
दानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम् ॥ १ ॥
अहिंसा सत्यमक्रोधस्त्याग: शान्तिरपैश‍ुनम् ।
दया भूतेष्वलोलुप्‍त्वं मार्दवं ह्रीरचापलम् ॥ २ ॥
तेज: क्षमा धृति: शौचमद्रोहो नातिमानिता ।
भवन्ति सम्पदं दैवीमभिजातस्य भारत ॥ ३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4125,\"bb\":3627,\"url_path\":\"/en/library/bg/16/1-3/b3627/\",\"body_value\":\"śrī-bhagavān uvāca
abhayaṁ sattva-saṁśuddhir
jñāna-yoga-vyavasthitiḥ
dānaṁ damaś ca yajñaś ca
svādhyāyas tapa ārjavam\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4126,\"bb\":3628,\"url_path\":\"/en/library/bg/16/1-3/b3628/\",\"body_value\":\"ahiṁsā satyam akrodhas
tyāgaḥ śāntir apaiśunam
dayā bhūteṣv aloluptvaṁ
mārdavaṁ hrīr acāpalam\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4127,\"bb\":3629,\"url_path\":\"/en/library/bg/16/1-3/b3629/\",\"body_value\":\"tejaḥ kṣamā dhṛtiḥ śaucam
adroho nāti-mānitā
bhavanti sampadaṁ daivīm
abhijātasya bhārata\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4128,\"bb\":3630,\"url_path\":\"/en/library/bg/16/1-3/b3630/\",\"shadow_value\":\"$25\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"abhayam\",\"translation\":\"fearlessness\"},{\"word\":\"sattva-saṁśuddhiḥ\",\"translation\":\"purification of one’s existence\"},{\"word\":\"jñāna\",\"translation\":\"in knowledge\"},{\"word\":\"yoga\",\"translation\":\"of linking up\"},{\"word\":\"vyavasthitiḥ\",\"translation\":\"the situation\"},{\"word\":\"dānam\",\"translation\":\"charity\"},{\"word\":\"damaḥ\",\"translation\":\"controlling the mind\"},{\"word\":\"ca\",\"translation\":\"and\"},{\"word\":\"yajñaḥ\",\"translation\":\"performance of sacrifice\"},{\"word\":\"ca\",\"translation\":\"and\"},{\"word\":\"svādhyāyaḥ\",\"translation\":\"study of Vedic literature\"},{\"word\":\"tapaḥ\",\"translation\":\"austerity\"},{\"word\":\"ārjavam\",\"translation\":\"simplicity\"},{\"word\":\"ahiṁsā\",\"translation\":\"nonviolence\"},{\"word\":\"satyam\",\"translation\":\"truthfulness\"},{\"word\":\"akrodhaḥ\",\"translation\":\"freedom from anger\"},{\"word\":\"tyāgaḥ\",\"translation\":\"renunciation\"},{\"word\":\"śāntiḥ\",\"translation\":\"tranquillity\"},{\"word\":\"apaiśunam\",\"translation\":\"aversion to fault-finding\"},{\"word\":\"dayā\",\"translation\":\"mercy\"},{\"word\":\"bhūteṣu\",\"translation\":\"towards all living entities\"},{\"word\":\"aloluptvam\",\"translation\":\"freedom from greed\"},{\"word\":\"mārdavam\",\"translation\":\"gentleness\"},{\"word\":\"hrīḥ\",\"translation\":\"modesty\"},{\"word\":\"acāpalam\",\"translation\":\"determination\"},{\"word\":\"tejaḥ\",\"translation\":\"vigor\"},{\"word\":\"kṣamā\",\"translation\":\"forgiveness\"},{\"word\":\"dhṛtiḥ\",\"translation\":\"fortitude\"},{\"word\":\"śaucam\",\"translation\":\"cleanliness\"},{\"word\":\"adrohaḥ\",\"translation\":\"freedom from envy\"},{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"ati-mānitā\",\"translation\":\"expectation of honor\"},{\"word\":\"bhavanti\",\"translation\":\"are\"},{\"word\":\"sampadam\",\"translation\":\"the qualities\"},{\"word\":\"daivīm\",\"translation\":\"the transcendental nature\"},{\"word\":\"abhijātasya\",\"translation\":\"of one who is born of\"},{\"word\":\"bhārata\",\"translation\":\"O son of Bharata\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4129,\"bb\":3631,\"url_path\":\"/en/library/bg/16/1-3/b3631/\",\"body_value\":\"The Supreme Personality of Godhead said: Fearlessness; purification of one’s existence; cultivation of spiritual knowledge; charity; self-control; performance of sacrifice; study of the Vedas; austerity; simplicity; nonviolence; truthfulness; freedom from anger; renunciation; tranquillity; aversion to faultfinding; compassion for all living entities; freedom from covetousness; gentleness; modesty; steady determination; vigor; forgiveness; fortitude; cleanliness; and freedom from envy and from the passion for honor – these transcendental qualities, O son of Bharata, belong to godly men endowed with divine nature.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4130,\"bb\":3632,\"url_path\":\"/en/library/bg/16/1-3/b3632/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4131,\"bb\":3633,\"url_path\":\"/en/library/bg/16/1-3/b3633/\",\"body_value\":\"The word abhijātasya in reference to one born of transcendental qualities or godly tendencies is very significant. To beget a child in a godly atmosphere is known in the Vedic scriptures as Garbhādhāna-saṁskāra. If the parents want a child in the godly qualities they should follow the ten principles recommended for the social life of the human being. In Bhagavad-gītā we have studied also before that sex life for begetting a good child is Kṛṣṇa Himself. Sex life is not condemned, provided the process is used in Kṛṣṇa consciousness. Those who are in Kṛṣṇa consciousness at least should not beget children like cats and dogs but should beget them so that they may become Kṛṣṇa conscious after birth. That should be the advantage of children born of a father and mother absorbed in Kṛṣṇa consciousness.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4132,\"bb\":3634,\"url_path\":\"/en/library/bg/16/1-3/b3634/\",\"body_value\":\"The social institution known as varṇāśrama-dharma – the institution dividing society into four divisions of social life and four occupational divisions or castes – is not meant to divide human society according to birth. Such divisions are in terms of educational qualifications. They are to keep the society in a state of peace and prosperity. The qualities mentioned herein are explained as transcendental qualities meant for making a person progress in spiritual understanding so that he can get liberated from the material world.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4133,\"bb\":3635,\"url_path\":\"/en/library/bg/16/1-3/b3635/\",\"body_value\":\"$27\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4134,\"bb\":3636,\"url_path\":\"/en/library/bg/16/1-3/b3636/\",\"body_value\":\"$28\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4135,\"bb\":3637,\"url_path\":\"/en/library/bg/16/1-3/b3637/\",\"body_value\":\"$29\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4136,\"bb\":3638,\"url_path\":\"/en/library/bg/16/1-3/b3638/\",\"body_value\":\"The next item is charity. Charity is meant for the householders. The householders should earn a livelihood by an honorable means and spend fifty percent of their income to propagate Kṛṣṇa consciousness all over the world. Thus a householder should give in charity to institutional societies that are engaged in that way. Charity should be given to the right receiver. There are different kinds of charity, as will be explained later on – charity in the modes of goodness, passion and ignorance. Charity in the mode of goodness is recommended by the scriptures, but charity in the modes of passion and ignorance is not recommended, because it is simply a waste of money. Charity should be given only to propagate Kṛṣṇa consciousness all over the world. That is charity in the mode of goodness.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4137,\"bb\":3639,\"url_path\":\"/en/library/bg/16/1-3/b3639/\",\"body_value\":\"Then as far as dama (self-control) is concerned, it is not only meant for other orders of religious society, but is especially meant for the householder. Although he has a wife, a householder should not use his senses for sex life unnecessarily. There are restrictions for the householders even in sex life, which should only be engaged in for the propagation of children. If he does not require children, he should not enjoy sex life with his wife. Modern society enjoys sex life with contraceptive methods or more abominable methods to avoid the responsibility of children. This is not in the transcendental quality, but is demoniac. If anyone, even if he is a householder, wants to make progress in spiritual life, he must control his sex life and should not beget a child without the purpose of serving Kṛṣṇa. If he is able to beget children who will be in Kṛṣṇa consciousness, one can produce hundreds of children, but without this capacity one should not indulge only for sense pleasure.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4138,\"bb\":3640,\"url_path\":\"/en/library/bg/16/1-3/b3640/\",\"body_value\":\"Sacrifice is another item to be performed by the householders, because sacrifices require a large amount of money. Those in other orders of life, namely brahmacarya, vānaprastha and sannyāsa, have no money; they live by begging. So performance of different types of sacrifice is meant for the householders. They should perform agni-hotra sacrifices as enjoined in the Vedic literature, but such sacrifices at the present moment are very expensive, and it is not possible for any householder to perform them. The best sacrifice recommended in this age is called saṅkīrtana-yajña. This saṅkīrtana-yajña, the chanting of Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare, is the best and most inexpensive sacrifice; everyone can adopt it and derive benefit. So these three items, namely charity, sense control and performance of sacrifice, are meant for the householder.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4139,\"bb\":3641,\"url_path\":\"/en/library/bg/16/1-3/b3641/\",\"body_value\":\"Then svādhyāya, Vedic study, is meant for brahmacarya, or student life. Brahmacārīs should have no connection with women; they should live a life of celibacy and engage the mind in the study of Vedic literature for cultivation of spiritual knowledge. This is called svādhyāya.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4140,\"bb\":3642,\"url_path\":\"/en/library/bg/16/1-3/b3642/\",\"body_value\":\"$2a\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4141,\"bb\":3643,\"url_path\":\"/en/library/bg/16/1-3/b3643/\",\"body_value\":\"As far as the brahminical quality of simplicity is concerned, not only should a particular order of life follow this principle, but every member, be he in the brahmacārī āśrama, gṛhastha āśrama, vānaprastha āśrama or sannyāsa āśrama. One should be very simple and straightforward.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4142,\"bb\":3644,\"url_path\":\"/en/library/bg/16/1-3/b3644/\",\"body_value\":\"$2b\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4143,\"bb\":3645,\"url_path\":\"/en/library/bg/16/1-3/b3645/\",\"body_value\":\"Satyam. This word means that one should not distort the truth for some personal interest. In Vedic literature there are some difficult passages, but the meaning or the purpose should be learned from a bona fide spiritual master. That is the process for understanding the Vedas. Śruti means that one should hear from the authority. One should not construe some interpretation for his personal interest. There are so many commentaries on Bhagavad-gītā that misinterpret the original text. The real import of the word should be presented, and that should be learned from a bona fide spiritual master.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4144,\"bb\":3646,\"url_path\":\"/en/library/bg/16/1-3/b3646/\",\"body_value\":\"Akrodha means to check anger. Even if there is provocation one should be tolerant, for once one becomes angry his whole body becomes polluted. Anger is a product of the mode of passion and lust, so one who is transcendentally situated should check himself from anger. Apaiśunam means that one should not find fault with others or correct them unnecessarily. Of course to call a thief a thief is not faultfinding, but to call an honest person a thief is very much offensive for one who is making advancement in spiritual life. Hrī means that one should be very modest and must not perform some act which is abominable. Acāpalam, determination, means that one should not be agitated or frustrated in some attempt. There may be failure in some attempt, but one should not be sorry for that; he should make progress with patience and determination.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4145,\"bb\":3647,\"url_path\":\"/en/library/bg/16/1-3/b3647/\",\"body_value\":\"The word tejas used here is meant for the kṣatriyas. The kṣatriyas should always be very strong to be able to give protection to the weak. They should not pose themselves as nonviolent. If violence is required, they must exhibit it. But a person who is able to curb down his enemy may under certain conditions show forgiveness. He may excuse minor offenses.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4146,\"bb\":3648,\"url_path\":\"/en/library/bg/16/1-3/b3648/\",\"body_value\":\"Śaucam means cleanliness, not only in mind and body but in one’s dealings also. It is especially meant for the mercantile people, who should not deal in the black market. Nāti-mānitā, not expecting honor, applies to the śūdras, the worker class, which are considered, according to Vedic injunctions, to be the lowest of the four classes. They should not be puffed up with unnecessary prestige or honor and should remain in their own status. It is the duty of the śūdras to offer respect to the higher class for the upkeep of the social order.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4147,\"bb\":3649,\"url_path\":\"/en/library/bg/16/1-3/b3649/\",\"body_value\":\"All these twenty-six qualifications mentioned are transcendental qualities. They should be cultivated according to the different statuses of social and occupational order. The purport is that even though material conditions are miserable, if these qualities are developed by practice, by all classes of men, then gradually it is possible to rise to the highest platform of transcendental realization.\"}]}],\"short_title\":\"Bg. 16.1-3\",\"medium_title\":\"Bhagavad-gītā As It Is 16.1-3\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L2c\",\"$L2d\",\"$L2e\"]}]\n"])self.__next_f.push([1,"30:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n36:I[78455,[\"/