\",\"wfwundefined-0-ca\",{\"href\":\"/en/search/synonyms/?original=ca\",\"children\":[\"$\",\"em\",null,{\"children\":\"ca\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"and\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yajñaḥ\",{\"href\":\"/en/search/synonyms/?original=yajñaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"yajñaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"performance of sacrifice\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ca\",{\"href\":\"/en/search/synonyms/?original=ca\",\"children\":[\"$\",\"em\",null,{\"children\":\"ca\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"and\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-svādhyāyaḥ\",{\"href\":\"/en/search/synonyms/?original=svādhyāyaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"svādhyāyaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"study of Vedic literature\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[\"$L38\"],\" — \",\"$L39\",\"; \"]}],\"$L3a\",\"$L3b\",\"$L3c\",\"$L3d\",\"$L3e\",\"$L3f\",\"$L40\",\"$L41\",\"$L42\",\"$L43\",\"$L44\",\"$L45\",\"$L46\",\"$L47\",\"$L48\",\"$L49\",\"$L4a\",\"$L4b\",\"$L4c\",\"$L4d\",\"$L4e\",\"$L4f\",\"$L50\",\"$L51\",\"$L52\"]}]}]]]}]\n"])self.__next_f.push([1,"34:[\"$\",\"div\",\"4123-translation,4123-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L30\",\"child-4129\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"The Supreme Personality of Godhead said: Fearlessness; purification of one’s existence; cultivation of spiritual knowledge; charity; self-control; performance of sacrifice; study of the Vedas; austerity; simplicity; nonviolence; truthfulness; freedom from anger; renunciation; tranquillity; aversion to faultfinding; compassion for all living entities; freedom from covetousness; gentleness; modesty; steady determination; vigor; forgiveness; fortitude; cleanliness; and freedom from envy and from the passion for honor – these transcendental qualities, O son of Bharata, belong to godly men endowed with divine nature.\"}}]}]}]]]}]\n53:T475,In the beginning of the Fifteenth Chapter, the banyan tree of this material world was explained. The extra roots coming out of it were compared to the activities of the living entities, some auspicious, some inauspicious. In the Ninth Chapter, also, the devas, or godly, and the asuras, the ungodly, or demons, were explained. Now, according to Vedic rites, activities in the mode of goodness are considered auspicious for progress on the path of liberation, and such activities are known as daivī prakṛti, transcendental by nature. Those who are situated in the transcendental nature make progress on the path of liberation. For those who are acting in the modes of passion and ignorance, on the other hand, there is no possibility of liberation. Either they will have to remain in this material world as human beings, or they will descend among the species of animals or even lower life forms. In this Sixteenth Chapter the Lord explains both the transcendental nature and its attendant qualities and the demoniac nature and its qualities. He also explains the advantages and disadvantages of these qualities.54:T603,"])self.__next_f.push([1,"In the varṇāśrama institution the sannyāsī, or the person in the renounced order of life, is considered to be the head or the spiritual master of all the social statuses and orders. A brāhmaṇa is considered to be the spiritual master of the three other sections of a society, namely, the kṣatriyas, the vaiśyas and the śūdras, but a sannyāsī, who is on the top of the institution, is considered to be the spiritual master of the brāhmaṇas also. For a sannyāsī, the first qualification should be fearlessness. Because a sannyāsī has to be alone without any support or guarantee of support, he has simply to depend on the mercy of the Supreme Personality of Godhead. If one thinks, “After I leave my connections, who will protect me?” he should not accept the renounced order of life. One must be fully convinced that Kṛṣṇa or the Supreme Personality of Godhead in His localized aspect as Paramātmā is always within, that He is seeing everything, and He always knows what one intends to do. One must thus have firm conviction that Kṛṣṇa as Paramātmā will take care of a soul surrendered to Him. “I shall never be alone,” one should think. “Even if I live in the darkest regions of a forest I shall be accompanied by Kṛṣṇa, and He will give me all protection.” That conviction is called abhayam, fearlessness. This state of mind is necessary for a person in the renounced order of life."])self.__next_f.push([1,"35:[\"$\",\"div\",\"4123-purport,4123-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L30\",\"child-4130\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$53\"}}]}],[\"$\",\"$L30\",\"child-4131\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The word abhijātasya in reference to one born of transcendental qualities or godly tendencies is very significant. To beget a child in a godly atmosphere is known in the Vedic scriptures as Garbhādhāna-saṁskāra. If the parents want a child in the godly qualities they should follow the ten principles recommended for the social life of the human being. In Bhagavad-gītā we have studied also before that sex life for begetting a good child is Kṛṣṇa Himself. Sex life is not condemned, provided the process is used in Kṛṣṇa consciousness. Those who are in Kṛṣṇa consciousness at least should not beget children like cats and dogs but should beget them so that they may become Kṛṣṇa conscious after birth. That should be the advantage of children born of a father and mother absorbed in Kṛṣṇa consciousness.\"}}]}],[\"$\",\"$L30\",\"child-4132\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The social institution known as varṇāśrama-dharma – the institution dividing society into four divisions of social life and four occupational divisions or castes – is not meant to divide human society according to birth. Such divisions are in terms of educational qualifications. They are to keep the society in a state of peace and prosperity. The qualities mentioned herein are explained as transcendental qualities meant for making a person progress in spiritual understanding so that he can get liberated from the material world.\"}}]}],[\"$\",\"$L30\",\"child-4133\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$54\"}}]}],\"$L55\",\"$L56\",\"$L57\",\"$L58\",\"$L59\",\"$L5a\",\"$L5b\",\"$L5c\",\"$L5d\",\"$L5e\",\"$L5f\",\"$L60\",\"$L61\",\"$L62\"]]}]\n"])self.__next_f.push([1,"63:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://t.me/online_vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Telegram\",\"aria-label\":\"Vedabase Telegram\",\"children\":[\"$\",\"svg\",null,{\"stroke\":\"currentColor\",\"fill\":\"currentColor\",\"strokeWidth\":\"0\",\"viewBox\":\"0 0 496 512\",\"className\":\"inline w-8 h-8 mr-4\",\"children\":[\"$undefined\",[[\"$\",\"path\",\"0\",{\"d\":\"M248 8C111 8 0 119 0 256s111 248 