mt-6\",\"children\":[\"$\",\"a\",null,{\"href\":\"https://dashboard.simpleanalytics.com/?utm_source=vedabase.io&utm_content=badge\",\"referrerPolicy\":\"origin\",\"target\":\"_blank\",\"children\":[\"$\",\"picture\",null,{\"children\":\"$63\"}]}]}]]}]\n"])self.__next_f.push([1,"38:[\"$\",\"$L20\",\"wfwundefined-0-tapaḥ\",{\"href\":\"/en/search/synonyms/?original=tapaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"tapaḥ\"}]}]\n39:[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"austerity\"}}]\n3a:[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ārjavam\",{\"href\":\"/en/search/synonyms/?original=ārjavam\",\"children\":[\"$\",\"em\",null,{\"children\":\"ārjavam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"simplicity\"}}],\"; \"]}]\n3b:[\"$\",\"span\",\"wfwundefined-14\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ahiṁsā\",{\"href\":\"/en/search/synonyms/?original=ahiṁsā\",\"children\":[\"$\",\"em\",null,{\"children\":\"ahiṁsā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"nonviolence\"}}],\"; \"]}]\n3c:[\"$\",\"span\",\"wfwundefined-15\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-satyam\",{\"href\":\"/en/search/synonyms/?original=satyam\",\"children\":[\"$\",\"em\",null,{\"children\":\"satyam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"truthfulness\"}}],\"; \"]}]\n3d:[\"$\",\"span\",\"wfwundefined-16\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-akrodhaḥ\",{\"href\":\"/en/search/synonyms/?original=akrodhaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"akrodhaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"freedom from anger\"}}],\"; \"]}]\n3e:[\"$\",\"span\",\"wfwundefined-17\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tyāgaḥ\",{\"href\":\"/en/search/synonyms/?original=tyāgaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"tyāgaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"renunciation\"}}],\"; \"]}]\n3f:[\"$\",\"span\",\"wfwundefined-18\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-śāntiḥ\",{\"href\":\"/en/search/synonyms/?original=śāntiḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"śāntiḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"tranquillity\"}}],\"; \"]}]\n40:[\"$\",\"span\",\"wfwundefined-19\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-apaiśunam\",{\"href\":\"/en/search/synonyms/?original=apaiśunam\",\"children\":[\"$\",\"em\",null,{\"children\":\"apaiśunam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"aversion to fault-finding\"}}],\"; \"]}]\n41:[\"$\",\"span\",\"wfwundefined-20\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-dayā\",{\"href\":\"/en/search/synonyms/?original=dayā\",\"children\":[\"$\",\"em\",null,{\"children\":\"dayā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"mercy\"}}],\"; \"]}]\n42:[\"$\",\"span\",\"wfwundefined-21\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhūteṣu\",{\"href\":\"/en/search/synonyms/?original=bhūteṣu\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhūteṣu\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"towards all living entities\"}}],\"; \"]}]\n43:[\"$\",\"span\",\"wfwundefined-22\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-aloluptvam\",{\"href\":\"/en/search/synonyms/?original=al